import java.util.Map;

public final class FeeCalculator {
    private static final int REMOTE_SURCHARGE = 8;

    private final Map<Integer, Template> templates = Map.of(
            1032, new Template(18, 4));
    private final Map<String, Region> regions = Map.of(
            "新疆", new Region(3),
            "西藏", new Region(3));

    public int calc(Req r) {
        if (isRemoteProvince(r.province)) {
            return calcRemoteFee(r);
        }
        return calcStandardFee(r);
    }

    public int calcRemoteFee(Req r) {
        return calcStandardFee(r) + REMOTE_SURCHARGE;
    }

    private int calcStandardFee(Req r) {
        int fee = tpl(r.tplId).first;
        if (r.weight > 1.0) {
            int extra = (int) Math.ceil(r.weight - 1.0);
            int unit = tpl(r.tplId).next;
            if (r.vip) unit = unit / 2;
            fee += extra * unit;
        }
        if (region(r.province) != null) fee += region(r.province).surcharge;
        if (r.cod) fee += 2;
        return fee;
    }

    private boolean isRemoteProvince(String province) {
        return "新疆".equals(province) || "西藏".equals(province);
    }

    private Template tpl(int tplId) {
        return templates.get(tplId);
    }

    private Region region(String province) {
        return regions.get(province);
    }

    public static final class Req {
        final int tplId;
        final double weight;
        final boolean vip;
        final boolean cod;
        final String province;

        public Req(int tplId, double weight, boolean vip, boolean cod, String province) {
            this.tplId = tplId;
            this.weight = weight;
            this.vip = vip;
            this.cod = cod;
            this.province = province;
        }
    }

    private record Template(int first, int next) {}

    private record Region(int surcharge) {}
}

